    let emocao = Math.random() < 0.5 ? this.alvo : embaralhar(this.emocoes)[0]
    let bonus = false
    if (this.time.now > this.proximoBonus) {
      bonus = true
      emocao = null
      this.proximoBonus = this.time.now + INTERVALO_BONUS
    }
    const obj = imagem(this, x, -30, bonus ? 'estrela_bonus' : emocao.arte, TAMANHO_ROSTO)
    this.itens.push({ obj, emocao, bonus, fase: Math.random() * 6.28 })
  }

  update(_, dt) {
    if (this.fim) return
    const passo = dt / 1000

    if (this.setas.left.isDown) this.jogador.x -= 420 * passo
    if (this.setas.right.isDown) this.jogador.x += 420 * passo
    this.jogador.x = Phaser.Math.Clamp(this.jogador.x, 30, 770)

    const emSuper = this.time.now < this.superAte
    this.aura.setVisible(emSuper).setPosition(this.jogador.x, this.jogador.y)
    const raio = emSuper ? RAIO_SUPER : RAIO_NORMAL

    const queda = this.velocidadeQueda()
    for (const item of [...this.itens]) {
      item.obj.y += queda * passo
      // os rostos balançam enquanto caem
      if (this.ctx.efeitos) item.obj.setAngle(Math.sin(this.time.now / 220 + item.fase) * 14)
      const perto =
        Math.abs(item.obj.x - this.jogador.x) < raio && Math.abs(item.obj.y - this.jogador.y) < raio
      if (perto) this.pegar(item)
      else if (item.obj.y > 480) this.remover(item)
    }
  }

  remover(item) {
    item.obj.destroy()
    this.itens = this.itens.filter((i) => i !== item)
  }

  pegar(item) {
    const { x, y } = item.obj
    this.remover(item)

    if (item.bonus) {
      this.superAte = this.time.now + DURACAO_SUPER
      sons.desbloqueio()
      confete(this, x, y, { quantidade: 14 })
      this.mostrarDica('SUPER! Pegue tudo!')
      return
    }

    if (item.emocao === this.alvo) {
      this.acertos++
      this.combo++
      this.hud.acerto(this.jogador)
      estourar(this, this.jogador)
      if (this.combo >= 3) {
        confete(this, this.jogador.x, this.jogador.y - 20, { quantidade: 10 })
        this.mostrarDica(`Combo x${this.combo}!`)
      } else {
        this.mostrarDica('Isso!')
      }
      if (this.acertos >= META) return this.terminar()
      if (this.acertos % ACERTOS_POR_ALVO === 0) this.novoAlvo()
    } else {
      this.combo = 0
      this.hud.erro()
      balancar(this, this.jogador, 8)
      this.mostrarDica(`Quase! Procure: ${this.alvo.nome}`)
    }
  }

  mostrarDica(texto) {
    this.dica.setText(texto)
    this.dicaVersao = (this.dicaVersao ?? 0) + 1
    const versao = this.dicaVersao
    this.time.delayedCall(1200, () => {
      if (versao === this.dicaVersao) this.dica.setText('')
    })
  }

  terminar() {
    this.fim = true
    telaFinal(this, this.ctx, 'Muito bem!\nVocê reconheceu as emoções!')
  }
}
import { montarCena } from '../../compartilhado/kit-phaser/montarCena.js'
import ChuvaEmocoes from './ChuvaEmocoes.js'

export function montar(elemento, parametros) {
  return montarCena(elemento, ChuvaEmocoes, 'ChuvaEmocoes', parametros)
}
import Phaser from 'phaser'
import Boot from './Boot.js'
import { pararMusica } from './audio.js'
import { estado, registrarAcerto } from './progresso.js'

// Monta uma cena do kit (Chuva de emoções, Cuidar do amigo, Plataforma do amigo) no
// formato do contrato (jogos/contrato.js). A Boot carrega a arte e inicia a cena `chave`.
export function montarCena(elemento, Cena, chave, { tema, nivel = 1, opcoes = {}, aoTerminar, aoSair }) {
  let metricas = { attempts: 0, correct: 0, hints: 0 }
  let emAndamento = true
  let cancelado = false
  let game

  const entregar = (status) => {
    aoTerminar?.({ status, ...metricas })
    metricas = { attempts: 0, correct: 0, hints: 0 }
    emAndamento = false
  }

  const ctx = {
    aluno: 'hub',
    hiperfoco: tema,
    nivel,
    velocidade: 1,
    efeitos: !opcoes.reduzirMovimento,
    sons: opcoes.sons ?? true,
    musica: opcoes.musica ?? false,
    // o hub tem o próprio botão de sair, sempre no mesmo lugar
    mostrarSair: false,
    sair: () => aoSair?.(),
    concluir: () => entregar('completed'),
    estado: () => estado(tema),
    registrarAcerto: () => registrarAcerto(tema),
    registrarTentativa: (ok) => {
      emAndamento = true
      metricas.attempts++
      if (ok) metricas.correct++
    },
  }

  // o canvas só desenha com a fonte do jogo depois que ela carregou
  document.fonts
    .load('400 20px Fredoka')
    .catch(() => {})
    .then(() => {
      if (cancelado) return
      game = new Phaser.Game({
        type: Phaser.AUTO,
        parent: elemento,
        width: 800,
        height: 450,
        scale: { mode: Phaser.Scale.FIT, autoCenter: Phaser.Scale.CENTER_BOTH },
        physics: { default: 'arcade', arcade: { gravity: { y: 1100 } } },
        scene: [Boot, Cena],
        callbacks: {
          preBoot: (g) => {
            g.registry.set('ctx', ctx)
            g.registry.set('cena', chave)
          },
        },
      })
      // só para testes automáticos no modo de desenvolvimento
      if (import.meta.env?.DEV) window.__phaser = game
    })

  return function desmontar() {
    cancelado = true
    if (emAndamento) entregar('abandoned')
    pararMusica()
    game?.destroy(true)
  }
}
import Phaser from 'phaser'
import { carregarArte, criarAnimacoes } from './arte.js'

// Carrega toda a arte (SVG desenhados em código) e inicia a cena do jogo escolhido.
export default class Boot extends Phaser.Scene {
  constructor() {
    super('Boot')
  }

  preload() {
    this.cameras.main.setBackgroundColor('#1f2a38')
    const texto = this.add
      .text(400, 225, 'Carregando...', { fontFamily: 'Fredoka, sans-serif', fontSize: '28px', color: '#ffffff' })
      .setOrigin(0.5)
    this.load.on('progress', (v) => texto.setText(`Carregando... ${Math.round(v * 100)}%`))
    carregarArte(this)
  }

  create() {
    criarAnimacoes(this)
    this.scene.start(this.registry.get('cena'))
  }
}
import { ARTE, urlDoQuadro } from '../arte/index.js'

// Ponte entre a arte (SVG em src/arte) e o Phaser: carrega todas as imagens uma vez, cria
// as animações por quadros e entrega sprites prontos para as cenas.
export const chave = (id, quadro = 0) => `${id}#${quadro}`

export function carregarArte(scene) {
  for (const [id, desc] of Object.entries(ARTE)) {
    desc.frames.forEach((_, i) => {
      scene.load.svg(chave(id, i), urlDoQuadro(id, i), { width: desc.px, height: desc.px })
    })
  }
}

export function criarAnimacoes(scene) {
  for (const [id, desc] of Object.entries(ARTE)) {
    if (desc.frames.length < 2) continue
    const sequencia = desc.seq ?? desc.frames.map((_, i) => i)
    scene.anims.create({
      key: id,
      frames: sequencia.map((i) => ({ key: chave(id, i) })),
      frameRate: desc.fps ?? 6,
      repeat: -1,
    })
  }
}

const animado = (scene, id) => ARTE[id].frames.length > 1 && scene.ctx?.efeitos !== false

// Sprite quadrado de `tamanho` pixels. Se a arte tem vários quadros, anima (a menos que
// `parado`, ou que "Reduzir efeitos" esteja ligado).
export function imagem(scene, x, y, id, tamanho, { parado = false } = {}) {
  if (!ARTE[id]) throw new Error(`Arte inexistente: ${id}`)
  const sprite = scene.add.sprite(x, y, chave(id, 0)).setDisplaySize(tamanho, tamanho)
  sprite.arteId = id
  if (!parado && animado(scene, id)) sprite.play(id)
  return sprite
}

// Troca o desenho de um sprite mantendo o tamanho na tela.
export function trocarImagem(sprite, id, { parado = false } = {}) {
  const { displayWidth, displayHeight } = sprite
  sprite.stop()
  sprite.setTexture(chave(id, 0))
  sprite.setDisplaySize(displayWidth, displayHeight)
  sprite.arteId = id
  if (!parado && animado(sprite.scene, id)) sprite.play(id)
}

// Ver imagem parada (primeiro quadro) ou animada, conforme o personagem anda.
export function animar(sprite, ligado) {
  if (!animado(sprite.scene, sprite.arteId) || sprite.animando === ligado) return
  sprite.animando = ligado
  if (ligado) sprite.play(sprite.arteId)
  else {
    sprite.stop()
    sprite.setTexture(chave(sprite.arteId, 0))
  }
}

