  // painel da pontuação (próximo item + barra) com cantos arredondados
  fixo(scene.add.rectangle(8, 4, 264, 52, 0x000000, 0.4).setOrigin(0, 0).setRounded(RAIO)).setDepth(39)
  const rotuloA = fixo(scene.add.text(20, 8, '', estiloRotulo))
  const rotuloIcone = fixo(imagem(scene, 0, 19, 'estrela', 24, { parado: true })).setVisible(false)
  const rotuloB = fixo(scene.add.text(20, 8, '', estiloRotulo))
  fixo(scene.add.rectangle(20, 40, larguraBarra, 10, 0xffffff, 0.25).setOrigin(0, 0.5).setRounded(5))
  const barra = fixo(scene.add.rectangle(20, 40, 10, 10, 0xffd447).setOrigin(0, 0.5).setRounded(5))
  if (ctx.mostrarSair !== false) {
    const sair = botao(scene, 740, 26, 90, 34, 'Sair', () => ctx.sair(), 0x555555)
    sair.r.setDepth(40)
    sair.t.setDepth(41)
  }

  function atualizar(e) {
    if (e.proximo) {
      rotuloA.setText('Próximo:')
      const x = 20 + rotuloA.width + 8
      trocarImagem(rotuloIcone, e.proximo.arte, { parado: true })
      rotuloIcone.setPosition(x + 12, 19).setVisible(true)
      rotuloB.setText(e.proximo.nome).setPosition(x + 30, 8)
      const pct = (e.total - e.anterior) / (e.limite - e.anterior)
      barra.setSize(Math.max(10, larguraBarra * pct), 10)
    } else {
      rotuloA.setText('Coleção completa!')
      rotuloIcone.setVisible(false)
      rotuloB.setText('')
      barra.setSize(larguraBarra, 10)
    }
    return e
  }

  function mostrarDesbloqueio(item) {
    const fundo = scene.add.rectangle(0, 0, 300, 250, 0x000000, 0.85).setRounded(RAIO + 6)
    const titulo = scene.add.text(0, -92, 'Novo item!', { fontFamily: FONTE, fontSize: '30px', color: '#ffe9a8' }).setOrigin(0.5)
    const figura = imagem(scene, 0, -10, item.arte, 120, { parado: true })
    const nome = scene.add
      .text(0, 82, item.nome, { fontFamily: FONTE, fontSize: '26px', color: '#ffffff', align: 'center', wordWrap: { width: 270 } })
      .setOrigin(0.5)
    const aviso = scene.add.container(400, 225, [fundo, titulo, figura, nome]).setScrollFactor(0).setDepth(45)
    if (ctx.efeitos) {
      aviso.setScale(0.2)
      scene.tweens.add({ targets: aviso, scale: 1, duration: 350, ease: 'Back.Out' })
      scene.tweens.add({ targets: figura, angle: { from: -8, to: 8 }, duration: 300, yoyo: true, repeat: 5 })
    }
    sons.desbloqueio()
    confete(scene, 400, 225, { quantidade: 28, espalhar: 220, fixo: true })
    scene.time.delayedCall(2200, () => aviso.destroy())
  }

  atualizar(ctx.estado())

  return {
    // `origem` (opcional): objeto de onde saem as estrelinhas do acerto
    acerto(origem) {
      ctx.registrarTentativa(true)
      sons.acerto()
      if (origem) confete(scene, origem.x, origem.y - 20)
      const e = atualizar(ctx.registrarAcerto())
      if (e.novoItem) mostrarDesbloqueio(e.novoItem)
    },
    erro() {
      ctx.registrarTentativa(false)
      sons.erro()
    },
  }
}

export function telaFinal(scene, ctx, mensagem) {
  ctx.concluir?.()
  sons.fim()
  chuvaDeConfete(scene)
  scene.add.rectangle(400, 225, 800, 450, 0x000000, 0.7).setScrollFactor(0).setDepth(50)
  const trofeu = imagem(scene, 400, 82, 'trofeu', 96, { parado: true }).setScrollFactor(0).setDepth(51)
  if (ctx.efeitos) {
    scene.tweens.add({ targets: trofeu, angle: { from: -8, to: 8 }, duration: 400, yoyo: true, repeat: -1, ease: 'Sine.InOut' })
  }
  caixaTexto(
    scene,
    400,
    175,
    mensagem,
    { fontSize: '32px', color: '#ffffff', align: 'center' },
    { px: 32, py: 14, alpha: 0.5, depth: 51, fixo: true },
  )
  const a = botao(scene, 280, 290, 220, 60, 'Jogar de novo', () => scene.scene.restart(), 0x2e9e5b)
  const b = botao(scene, 520, 290, 220, 60, 'Voltar ao menu', () => ctx.sair(), 0x555555)
  for (const o of [a, b]) {
    o.r.setDepth(53)
    o.t.setDepth(54)
  }
}

export function embaralhar(lista) {
  const copia = [...lista]
  for (let i = copia.length - 1; i > 0; i--) {
    const j = Math.floor(Math.random() * (i + 1))
    ;[copia[i], copia[j]] = [copia[j], copia[i]]
  }
  return copia
}
import { chave } from './arte.js'

// Efeitos visuais de recompensa e de "vida" do cenário. Todos respeitam a opção
// "Reduzir efeitos" (ctx.efeitos = false): nesse caso não animam nada. As animações de
// escala são relativas à escala atual, porque os sprites têm tamanho em pixels.
const PARTICULAS = ['p_estrela', 'p_coracao', 'p_brilho', 'p_bolinha', 'p_fita']
const entre = (a, b) => a + Math.random() * (b - a)

// Explosão de estrelinhas e confete. `fixo` = coordenadas da tela, em vez do mundo da fase.
export function confete(scene, x, y, { quantidade = 16, espalhar = 100, fixo = false } = {}) {
  if (!scene.ctx.efeitos) return
  for (let i = 0; i < quantidade; i++) {
    const tamanho = entre(16, 30)
    const base = tamanho / 48 // as partículas são rasterizadas em 48 px
    const p = scene.add.image(x, y, chave(PARTICULAS[i % PARTICULAS.length])).setScale(base).setDepth(60)
    if (fixo) p.setScrollFactor(0)
    const angulo = entre(0, Math.PI * 2)
    const distancia = espalhar * entre(0.5, 1.2)
    const duracao = entre(800, 1300)
    scene.tweens.add({
      targets: p,
      x: x + Math.cos(angulo) * distancia,
      y: y + Math.sin(angulo) * distancia - 30,
      angle: entre(-180, 180),
      scale: base * 0.6,
      duration: duracao,
      ease: 'Cubic.Out',
      onComplete: () => p.destroy(),
    })
    // some só na segunda metade, para o confete ficar visível enquanto voa
    scene.tweens.add({ targets: p, alpha: 0, delay: duracao * 0.5, duration: duracao * 0.5 })
  }
}

// Várias explosões espalhadas pela tela, para as celebrações.
export function chuvaDeConfete(scene, rodadas = 4) {
  for (let i = 0; i < rodadas; i++) {
    scene.time.delayedCall(i * 260, () =>
      confete(scene, entre(120, 680), entre(80, 260), { quantidade: 14, espalhar: 110, fixo: true }),
    )
  }
}

// "Pulinho de alegria": estica e volta.
export function estourar(scene, alvo, forca = 1.3) {
  if (!scene.ctx.efeitos) return
  scene.tweens.add({
    targets: alvo,
    scaleX: alvo.scaleX * forca,
    scaleY: alvo.scaleY * forca,
    duration: 110,
    yoyo: true,
    ease: 'Quad.Out',
  })
}

// Balanço rápido de lado a lado (um "opa" gentil ou um aceno).
export function balancar(scene, alvo, graus = 10) {
  if (!scene.ctx.efeitos) return
  scene.tweens.add({
    targets: alvo,
    angle: { from: -graus, to: graus },
    duration: 90,
    yoyo: true,
    repeat: 3,
    onComplete: () => alvo.setAngle(0),
  })
}

// Respirar: o personagem cresce e encolhe devagar, parado ou não.
export function respirar(scene, alvo, forca = 0.06) {
  if (!scene.ctx.efeitos) return
  scene.tweens.add({
    targets: alvo,
    scaleY: alvo.scaleY * (1 + forca),
    scaleX: alvo.scaleX * (1 - forca / 2),
    duration: 700,
    yoyo: true,
    repeat: -1,
    ease: 'Sine.InOut',
  })
}

// Acena sem parar (amigos, bandeira).
export function acenar(scene, alvo, graus = 7, duracao = 500) {
  if (!scene.ctx.efeitos) return
  alvo.setAngle(-graus)
  scene.tweens.add({
    targets: alvo,
    angle: graus,
    duration: duracao,
    yoyo: true,
    repeat: -1,
    ease: 'Sine.InOut',
  })
}

// Nuvens que passam devagar ao fundo (cenas sem rolagem).
export function nuvens(scene, quantidade = 6) {
  for (let i = 0; i < quantidade; i++) {
    const tamanho = entre(90, 150)
    const n = scene.add
      .image(entre(0, 800), entre(70, 330), chave('nuvem'))
      .setDisplaySize(tamanho, tamanho)
      .setAlpha(0.35)
      .setDepth(-1)
    if (!scene.ctx.efeitos) continue
    scene.tweens.add({
      targets: n,
      x: n.x + entre(60, 140) * (i % 2 ? 1 : -1),
      duration: entre(5000, 9000),
      yoyo: true,
      repeat: -1,
      ease: 'Sine.InOut',
    })
  }
}

