  const {
    tamanho = 22,
    fonte = FONTES.negrito,
    cor = PAPEL.tintaCss,
    fundo = PAPEL.papel,
    px = 18,
    py = 8,
    largura,
    sombra = 4,
    depth = 0,
  } = opcoes
  const f = cartao(scene, x, y, 10, 10, { cor: fundo, sombra, raio: 16, depth })
  const t = scene.add
    .text(x, y, texto, {
      fontFamily: fonte,
      fontSize: `${tamanho}px`,
      color: cor,
      align: 'center',
      ...(largura ? { wordWrap: { width: largura } } : {}),
    })
    .setOrigin(0.5)
    .setDepth(depth + 1)
  const ajustar = () => {
    f.setVisible(t.text !== '')
    f.desenhar(t.width + px * 2, t.height + py * 2)
  }
  ajustar()
  return {
    t,
    f,
    setText(s) {
      t.setText(s)
      ajustar()
      return this
    },
    destroy() {
      f.destroy()
