    this.amigo.trocar(embaralhar(ANIMAIS_AMIGOS)[0])
    this.amigo.setAngle(0)
    this.cara.trocar(`rosto_${c.cara}`)
    this.cena.trocar(`cena_${c.cena}`, { parado: true })
