    const certos = embaralhar(c.certos).slice(0, Math.random() < 0.5 ? 1 : 2)
    const errados = embaralhar(c.errados).slice(0, 4 - certos.length)
    this.itens = embaralhar([...certos, ...errados]).map((id, i, todos) =>
