    this.cuidador = adesivo(this, 150, 262, hiperfoco.arte, 124, { sombra: 5 }).setDepth(5)

    this.input.on('dragstart', (_, obj) => {
      if (!this.travado && obj.item) this.anel.setVisible(true)
    })
    this.input.on('drag', (_, obj, x, y) => {
