        .image(this.cara.x + 16, this.cara.y + 12, chave('gota'))
        .setDisplaySize(18, 18)
        .setDepth(8)
      this.tweens.add({
        targets: gota,
        y: gota.y + 80,
        alpha: 0,
        duration: 900,
        onComplete: () => gota.destroy(),
      })
    }
  }

